  (* [comment removed for export] *)
  Definition tl_body2 (f : nat) (out1 : list Z) (s1a s2 : Z) (d1r : bitD) : res (list Z) :=
    if dcap - 2 <? FseNCount.Zlength out1 then Err ZSTD_error_dstSize_tooSmall
    else
      let! q2 := decode_sym dt false s2 d1r in let '(o1, s2a, d2) := q2 in
      let! r2 := reload_dstream bs d2 in let '(st2, d2r) := r2 in
      if dstatus_eqb st2 Overflow then
        let! q3 := decode_sym dt false s1a d2r in let '(o2, _, _) := q3 in
        Ok (out1 ++ [o1; o2])
      else tail_loop bs dt dcap false f (mkDec (out1 ++ [o1]) s1a s2a d2r).

  Lemma tail_loop_S : forall f x, tail_loop bs dt dcap false (Datatypes.S f) x =
    if dcap - 2 <? FseNCount.Zlength (de_out x) then Err ZSTD_error_dstSize_tooSmall
    else
      let! q1 := decode_sym dt false (de_s1 x) (de_bd x) in let '(o0, s1a, d1) := q1 in
      let! r1 := reload_dstream bs d1 in let '(st1, d1r) := r1 in
      if dstatus_eqb st1 Overflow then
        let! q2 := decode_sym dt false (de_s2 x) d1r in let '(o1, _, _) := q2 in
        Ok (de_out x ++ [o0; o1])
      else tl_body2 f (de_out x ++ [o0]) s1a (de_s2 x) d1r.
Proof.
