  Definition res_ok (r : res (list Z)) : Prop := match r with Ok _ | Err _ => True | Ub | NoFuel => False end.

  Notation HEADT x mm x8 x9 x18 x21 x22 x23 x30 x31 :=
    (TH 0x1c4f0 mm (Z_to_bv 64 (bd_bits (de_bd x))) (Z_to_bv 64 (de_s2 x)) (Z_to_bv 64 (de_s1 x)) x8 x9
        (Z_to_bv 64 (bd_reg S (de_bd x))) (Z_to_bv 64 (bd_cont (de_bd x))) x18 x21 x22 x23
        (Z_to_bv 64 (DST + zlen (de_out x) + 1)) x30 x31).

  Definition st_loop_stmt (f : nat) : Prop :=
    forall x r m1 (x8 x9 x18 x21 x22 x23 x30 x31 : word),
      tail_loop bs dt dcap false f x = r -> res_ok r -> bitd_ok bs (de_bd x) -> bd_bits (de_bd x) <= 2^29 ->
      zlen (de_out x) <= dcap - 2 ->
      sm_inv m0 DST dcap m1 (de_out x) -> st_K r ->
      evt psegs POST (HEADT x m1 x8 x9 x18 x21 x22 x23 x30 x31).

  (* [comment removed for export] *)
  Lemma st_h2 : forall f out1 s1a s2 d1r r m1 (b1 ns1 nb1 c : Z) (x9 x18 x21 x22 x23 : word),
    st_loop_stmt f ->
    tl_body2 f out1 s1a s2 d1r = r -> res_ok r ->
    bitd_ok bs d1r -> bd_bits d1r <= 64 -> bd_zero d1r = false ->
    zlen out1 <= dcap - 2 ->
    s1a = ns1 + Z.land (Z.shiftr c ((bv_swrap 32 (0 - b1) mod 18446744073709551616) mod 64)) (2^nb1 - 1) ->
    0 <= b1 <= 2^30 -> 0 <= c < 2^64 -> 0 <= nb1 <= 12 -> 0 <= ns1 < 65536 ->
    sm_inv m0 DST dcap m1 out1 -> st_K r ->
    evt psegs POST (TH 0x1c620 m1 (Z_to_bv 64 b1) (Z_to_bv 64 s2) (Z_to_bv 64 ns1) (Z_to_bv 64 (bd_bits d1r)) x9
                       (Z_to_bv 64 (S + bd_ptr d1r)) (Z_to_bv 64 c) x18 x21 x22 x23 (Z_to_bv 64 (DST + zlen out1))
                       (Z_to_bv 64 (bd_cont d1r)) (zx32 (Z_to_bv 64 (2^nb1 - 1)))).
Proof.
